            decoded := mload(0x40)

            // Extract the offset from the `results` parameter
            let offset := sub(results, 0x40)

            // Store the length of the decoded array
            let length := mload(offset)
            mstore(decoded, length)

            // Calculate the start and end pointers for the decoded array
            let decodedStart := add(decoded, 0x20)
            let decodedEnd := add(decodedStart, mul(length, 0x20))

